t=np.linspace(0,5,300);r0=.03;th=.04;k=.8;sig=.012;m=th+(r0-th)*np.exp(-k*t);sd=sig*np.sqrt((1-np.exp(-2*k*t))/(2*k));ax.plot(t,m*100,color=ACCENT,lw=2,label='conditional mean');ax.fill_between(t,(m-1.645*sd)*100,(m+1.645*sd)*100,color=ACCENT,alpha=.18,label='90% model band');ax.axhline(th*100,color=GOOD,ls='--',label='long-run level');ax.set_xlabel('Horizon (years)');ax.set_ylabel('Short rate (%)');ax.set_title('Mean reversion forgets the opening gap',loc='left');ax.legend(fontsize=8)
